import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledAppContainer = styled.div({
  position: 'relative',
  background: `linear-gradient(0deg, rgba(92, 72, 27, 0.04), rgba(92, 72, 27, 0.04)),
  linear-gradient(180deg, rgba(170, 106, 0, 0) 0%, rgba(195, 153, 85, 0.1) 100%),
  #FFFFFF`,
  minHeight: 'calc(100vh - 56px)',
});

export const StyledContent = styled.div({
  display: 'flex',
  justifyContent: 'space-between',
  gap: '24px',
});

interface StyledPaddingContentProps {
  $noPaddingTop?: boolean;
}

export const StyledPaddingContent = styled('div', {
  shouldForwardProp: (propName) => propName !== '$noPaddingTop',
})<StyledPaddingContentProps>(({ $noPaddingTop }) => ({
  padding: '24px',
  ...($noPaddingTop && { paddingTop: '0' }),
}));

type StyledHeaderBottomSeparator = 'none' | 'border' | 'margin';
type StyledHeaderTopSeparator = 'none' | 'border';
type StyledHeaderPadding = 'none' | 'small' | 'medium' | 'large';
type StyledHeaderBorderRadius = 'none' | 'small' | 'medium' | 'large';

interface StyledHeaderProps {
  $bottomSeparator?: StyledHeaderBottomSeparator;
  $topSepatator?: StyledHeaderTopSeparator;
  $fixedHeaderHeight?: boolean;
  $padding?: StyledHeaderPadding;
  $borderRadius?: StyledHeaderBorderRadius;
}

export const StyledHeader = styled('div', {
  shouldForwardProp: (propName) =>
    ![
      '$bottomSeparator',
      '$topSepatator',
      '$fixedHeaderHeight',
      '$padding',
      '$borderRadius',
    ].includes(propName),
})<StyledHeaderProps>(
  ({
    $bottomSeparator,
    $topSepatator,
    $fixedHeaderHeight,
    $padding,
    $borderRadius,
  }) => ({
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: '0 16px',
    padding: '20px 24px',
    background: 'white',
    borderRadius: '16px 16px 0 0',
    minHeight: '72px',
    ...($bottomSeparator === 'border' && {
      borderBottom: '1px solid #1414141F',
    }),
    ...($bottomSeparator === 'margin' && {
      borderRadius: '16px',
      boxShadow: '0px 0px 4px 0px #00000029',
      marginBottom: '16px',
    }),
    ...($topSepatator === 'border' && {
      borderTop: '1px solid #1414141F',
      borderRadius: '0px',
    }),
    ...($fixedHeaderHeight && { minHeight: '85px' }),
    ...($padding === 'none' && { padding: '0' }),
    ...($padding === 'small' && { padding: '12px 16px' }),
    ...($padding === 'medium' && { padding: '20px 24px' }),
    ...($padding === 'large' && { padding: '26px 24px' }),
    ...($borderRadius === 'none' && { borderRadius: '0' }),
    ...($borderRadius === 'small' && {
      borderRadius: `${theme.borderRadius['1']} ${theme.borderRadius['1']} 0 0`,
    }),
    ...($borderRadius === 'medium' && {
      borderRadius: `${theme.borderRadius['2']} ${theme.borderRadius['2']} 0 0`,
    }),
    ...($borderRadius === 'large' && {
      borderRadius: `${theme.borderRadius['4']} ${theme.borderRadius['4']} 0 0`,
    }),
  }),
);

type StyledRowContainerSpacing = 'none' | 'sm' | 'md' | 'lg';

interface StyledRowContainerProps {
  $marginBottom?: StyledRowContainerSpacing;
  $marginTop?: StyledRowContainerSpacing;
  $paddingBottom?: StyledRowContainerSpacing;
  $paddingTop?: StyledRowContainerSpacing;
}

const marginBottomStyles: Record<StyledRowContainerSpacing, string> = {
  none: '0',
  sm: '8px',
  md: '16px',
  lg: '24px',
};

const marginTopStyles: Record<StyledRowContainerSpacing, string> = {
  none: '0',
  sm: '8px',
  md: '16px',
  lg: '24px',
};

const paddingBottomStyles: Record<StyledRowContainerSpacing, string> = {
  none: '0',
  sm: '8px',
  md: '16px',
  lg: '24px',
};

const paddingTopStyles: Record<StyledRowContainerSpacing, string> = {
  none: '0',
  sm: '8px',
  md: '16px',
  lg: '24px',
};

export const StyledRowContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$marginBottom', '$marginTop', '$paddingBottom', '$paddingTop'].includes(
      propName,
    ),
})<StyledRowContainerProps>(
  ({
    $marginBottom = 'none',
    $marginTop = 'none',
    $paddingBottom = 'none',
    $paddingTop = 'none',
  }) => ({
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: marginBottomStyles[$marginBottom],
    marginTop: marginTopStyles[$marginTop],
    paddingBottom: paddingBottomStyles[$paddingBottom],
    paddingTop: paddingTopStyles[$paddingTop],
  }),
);

interface StyledMultiChartContainerProps {
  $isExportPage?: boolean;
  $quantity?: 1 | 2 | 3;
  $type?: 2;
}

export const StyledMultiChartContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$isExportPage', '$quantity', '$type'].includes(propName),
})<StyledMultiChartContainerProps>(({ $isExportPage, $quantity, $type }) => ({
  display: 'grid',
  gridTemplateColumns:
    'minmax(0px, 250px) minmax(0px, 798px) minmax(0px, 232px)',
  paddingBottom: '8px',
  ...($isExportPage && {
    gridTemplateColumns: '370px 880px 370px',
  }),
  ...($quantity === 1 && {
    gridTemplateColumns: '1fr',
    paddingBottom: '0',
  }),
  ...($quantity === 2 && {
    gridTemplateColumns: '1fr 2.2fr',
    paddingBottom: '0',
  }),
  ...($quantity === 3 && {
    gridTemplateColumns: '1fr 1.8fr 1fr',
    paddingBottom: '0',
  }),
  ...($type === 2 && {
    gridTemplateColumns: '249px 1012px',
    paddingBottom: '0',
  }),
}));
